      "detailUr": "ہندوستان کے دو مرتبہ قائم مقام وزیر اعظم رہے (1964 نہرو کے بعد، 1966 شاستری کے بعد)، مخلص گاندھیائی رہنما اور ماہر معاشیات۔",
